(function (LP) {
  'use strict';

  /*
   * The base event pack, shipped with the app (events come from js/data/baseEvents.js, generated by tools/build-events.py) and the same shape as an exported pack
   * (see js/rules/events/pack.js). Locked: campaigns can disable its entries or copy
   * them into a pack of their own, but not change it.
   *
   * conditions: the types of lasting state an event can leave behind. A type says
   * what a condition does; an instance (campaign.conditions) is one of them in play.
   * js/rules/conditions.js documents every field.
   */

  const credits = (amount) => ({ effect: 'resource', key: 'credits', amount: amount });

  const conditions = [
    /* ------------------------------------------------------------------ */
    /* Character                                                           */
    {
      id: 'refuses-battle', name: 'Refuses to fight', scope: 'character',
      text: 'Won\'t take part in any battle next turn, except an Invasion battle.',
      duration: { turns: 1, from: 'next' }, blocks: ['battle'], blockExcept: { battle: ['invasion'] }
    },
    {
      id: 'refuses-tasks', name: 'Refuses crew tasks', scope: 'character',
      text: 'Won\'t do any crew tasks next turn, but fights normally.',
      duration: { turns: 1, from: 'next' }, blocks: ['tasks']
    },
    {
      id: 'away', name: 'Away on business', scope: 'character',
      text: 'Away for two turns: no Upkeep, no tasks, no battles, and no events happen to them. They return with XP and a Loot Table item.',
      duration: { turns: 2, from: 'next' }, blocks: ['upkeep', 'tasks', 'battle', 'event-target'],
      on: { expire: [{ effect: 'xp', target: '$actor', amount: '1D6' }, { table: 'Loot Table' }] }
    },
    {
      id: 'no-xp', name: 'No XP', scope: 'character',
      text: 'Earns no XP next turn.',
      duration: { turns: 1, from: 'next' }, blocks: ['xp']
    },
    {
      id: 'extra-action', name: 'Extra action', scope: 'character',
      text: 'May take an additional action next turn, even from Sick Bay.',
      duration: { turns: 1, from: 'next' }, grants: ['extra-action']
    },
    {
      id: 'injury-ignore', name: 'Feeling great', scope: 'character',
      text: 'The next time they would roll on the Injury Table, the roll is ignored.',
      blocks: ['injury'], consumeOn: 'injuryRoll'
    },
    {
      id: 'missing-item', name: 'Missing item', scope: 'character',
      text: 'An item has gone missing. Next turn: Savvy 5+ and it turns up; otherwise it is lost for good.',
      duration: { turns: 1, from: 'next' }, check: { stat: 'savvy', dice: '1D6', target: 5 },
      on: {
        expire: [{ effect: 'item.restore', item: '$cond.params.item', to: '$actor' }],
        fail: [{ say: 'The item doesn\'t turn up. It is lost for good.', tone: 'bad' }, { effect: 'condition.remove', id: '$cond.id' }]
      }
    },
    {
      id: 'cant-fight', name: 'Lost', scope: 'character',
      text: 'Can\'t take part in this turn\'s battle.',
      duration: { turns: 1, from: 'now' }, blocks: ['battle']
    },
    {
      id: 'package', name: 'Package to deliver', scope: 'character',
      text: 'On arrival at a new world: 3 credits, then 1D6 — on 1-2 a Rival and +1 story point.',
      on: {
        arrive: [
          credits(3),
          { roll: '1D6', label: 'Trouble with the package', outcomes: [{ max: 2, steps: [{ effect: 'rival.add' }, { effect: 'resource', key: 'storyPoints', amount: 1 }] }] },
          { effect: 'condition.remove', id: '$cond.id' }
        ]
      }
    },
    {
      id: 'stay-or-pay', name: 'Wants to stay', scope: 'character',
      text: 'Likes this world. Before you leave, pay 1 story point or they stay behind.',
      asks: [{ key: 'pay', trigger: 'depart', label: '{actor} wants to stay on this world. Pay 1 story point to take them along?' }],
      on: {
        depart: [{
          if: { all: [{ var: '$pay' }, { fact: 'resource', key: 'storyPoints', gte: 1 }] },
          then: [{ effect: 'resource', key: 'storyPoints', amount: -1 }, { say: '{actor} comes along.' }],
          else: [{ effect: 'member.remove', target: '$actor' }]
        }]
      },
      consumeOn: 'depart'
    },

    /* ------------------------------------------------------------------ */
    /* Ship                                                                */
    {
      id: 'grounded', name: 'Grounded', scope: 'ship',
      text: 'The drive is resetting. The ship can\'t take off until it is done.',
      duration: { turns: 1, from: 'next' }, unique: 'extend', blocks: ['travel'],
      bypass: { label: 'Take off early (2D6 Hull damage)', steps: [{ effect: 'hull', amount: '-2D6' }] }
    },
    {
      id: 'life-support', name: 'Life support needs upgrading', scope: 'ship',
      text: 'The ship can\'t fly until the upgrade is paid for.',
      blocks: ['travel'], bypass: { label: 'Pay for the upgrade', cost: { key: 'credits', amount: 'params.cost' } }
    },
    {
      id: 'impounded', name: 'Impounded', scope: 'ship',
      text: 'The ship is impounded until the tax is paid.',
      blocks: ['travel'], bypass: { label: 'Pay the tax', cost: { key: 'credits', amount: 'params.cost' } }
    },
    {
      id: 'spare-parts', name: 'Spare parts', scope: 'ship',
      text: '+1 on Repair attempts. Used up on a natural 1.',
      modifiers: [{ target: 'roll.repair', add: 1 }], consumeOn: 'roll.repair'
    },

    /* ------------------------------------------------------------------ */
    /* Planet                                                              */
    {
      id: 'war-rumors', name: 'Rumors of war', scope: 'planet',
      text: 'Invasion rolls here are at +2 while you stay.',
      modifiers: [{ target: 'roll.invasion', add: 2 }], endsOn: 'depart'
    },
    {
      id: 'overstay', name: 'Outstaying your welcome', scope: 'planet',
      text: 'Every turn you stay here, add a Rival.',
      on: { stay: [{ effect: 'rival.add' }] }, endsOn: 'depart'
    },
    {
      id: 'lockdown', name: 'No ships may leave', scope: 'planet',
      text: 'You can\'t leave this planet.',
      duration: { turns: 2, from: 'next' }, blocks: ['travel']
    },

    /* ------------------------------------------------------------------ */
    /* Campaign                                                            */
    {
      id: 'cosmic-seen', name: 'Cosmic phenomenon seen', scope: 'campaign',
      text: 'The Cosmic phenomenon has happened. It can\'t happen again.', unique: 'ignore'
    },
    {
      id: 'on-quest', name: 'On a Quest', scope: 'campaign',
      text: 'The crew is pursuing a Quest. Rumors gained are Quest Rumors.', unique: 'ignore'
    },
    {
      id: 'no-invasion-next', name: 'Unity patrol nearby', scope: 'campaign',
      text: 'The world you arrive at this turn can\'t be Invaded.',
      duration: { turns: 1, from: 'now' }, unique: 'ignore'
    },
    {
      id: 'destinations', name: 'Worlds to choose from', scope: 'campaign',
      text: 'You must visit one of the worlds you looked up.',
      duration: { turns: 1, from: 'now' }, consumeOn: 'arrive'
    },
    {
      id: 'patron-offer', name: 'Patron job offered', scope: 'campaign',
      text: 'A Patron job is on offer this turn.',
      duration: { turns: 1, from: 'now' }, consumeOn: 'jobOffers'
    },
    {
      id: 'forced-rival', name: 'Rival to fight', scope: 'campaign',
      text: 'You must fight this Rival in your battle.',
      duration: { turns: 1, from: 'now' }, consumeOn: 'chooseBattle'
    },
    {
      id: 'tip', name: 'A tip on a Rival', scope: 'campaign',
      text: 'You may track down a Rival to fight this turn without a Track roll.',
      duration: { turns: 1, from: 'now' }, consumeOn: 'chooseBattle'
    },
    {
      id: 'small-job', name: 'Offered a small job', scope: 'campaign',
      text: 'In this turn\'s battle, mark a random enemy figure. If your crew kills them, earn 2 credits. Nothing if they run away.',
      duration: { turns: 1, from: 'now' },
      asks: [{ key: 'done', trigger: 'battleResult', label: 'Did your crew kill the marked enemy (small job)?' }],
      on: { battleResult: [{ if: { var: '$done' }, then: [credits(2)] }] }, consumeOn: 'battleResult'
    },
    {
      id: 'reward', name: 'Offered a reward', scope: 'campaign',
      text: 'In this turn\'s battle, mark a random terrain feature. A crew member who moves into contact and spends a Combat Action retrieves a package: 2 credits.',
      duration: { turns: 1, from: 'now' },
      asks: [{ key: 'done', trigger: 'battleResult', label: 'Did your crew retrieve the package (reward)?' }],
      on: { battleResult: [{ if: { var: '$done' }, then: [credits(2)] }] }, consumeOn: 'battleResult'
    },
    {
      id: 'promising-lead', name: 'Promising lead', scope: 'campaign',
      text: '+3 credits if you do an Opportunity mission this turn.',
      duration: { turns: 1, from: 'now' },
      on: { battleResult: [{ if: { fact: 'turn.mission', eq: 'opportunity' }, then: [credits(3)] }] }, consumeOn: 'battleResult'
    },
    {
      id: 'roll-bonus', name: 'Useful contact', scope: 'campaign',
      text: '+1 to the chosen roll next turn.',
      duration: { turns: 1, from: 'next' },
      modifiers: [{ target: 'roll.{params.roll}', add: 1 }], consumeOn: 'roll.{params.roll}'
    },
    {
      id: 'criminal-favor', name: 'A favor owed', scope: 'campaign',
      text: 'The next time you gain a Rival, roll 1D6: on 4+ that Rival is removed.',
      on: { rivalGained: [{ roll: '1D6', label: 'The favor', target: 4, pass: [{ effect: 'rival.disable', target: '$rival', reason: 'a favor repaid' }] }] },
      consumeOn: 'rivalGained'
    },
    {
      id: 'recruit-gift', name: 'Luxury trinket', scope: 'campaign',
      text: '+2 on one Recruit roll. Single-use.',
      modifiers: [{ target: 'roll.recruit', add: 2 }], consumeOn: 'roll.recruit'
    },
    {
      id: 'local-maps', name: 'Local maps', scope: 'campaign',
      text: 'If you receive a Quest on this world or the next, add 1 Rumor.',
      duration: { turns: 2, from: 'now' }, tickOn: 'arrive',
      on: { questGained: [{ effect: 'resource', key: 'rumors', amount: 1 }] }, consumeOn: 'questGained'
    },
    {
      id: 'supplies', name: 'Basic supplies', scope: 'campaign',
      text: 'Skip Upkeep costs for one campaign turn. Single-use.',
      asks: [{ key: 'use', trigger: 'upkeep', label: 'Use the Basic supplies and skip Upkeep costs this turn?' }],
      modifiers: [{ target: 'cost.upkeep', set: 0, ask: 'use' }], consumeOn: 'cost.upkeep'
    },
    {
      id: 'trade-goods', name: 'Trade goods', scope: 'campaign',
      text: 'On each new world, roll 1D6 for the credits the goods sell for. On a 1 they are worthless.',
      asks: [
        { key: 'roll', trigger: 'arrive', label: 'Roll for the price of your trade goods here?' },
        { key: 'sell', trigger: 'arrive', label: 'If the price is 2 or more, sell them?' }
      ],
      on: {
        arrive: [{
          if: { var: '$roll' },
          then: [{
            roll: '1D6', as: 'price', label: 'Trade goods price',
            outcomes: [
              { max: 1, steps: [{ say: 'The goods have perished.', tone: 'bad' }, { effect: 'condition.remove', id: '$cond.id' }] },
              { min: 2, steps: [{ if: { var: '$sell' }, then: [credits('$price'), { effect: 'condition.remove', id: '$cond.id' }], else: [{ say: 'You wait for a better price.' }] }] }
            ]
          }]
        }]
      }
    },
    {
      id: 'fuel-cell', name: 'Military fuel cell', scope: 'campaign',
      text: 'Zero travel costs for one jump. Single-use.',
      asks: [{ key: 'use', trigger: 'depart', label: 'Use the military fuel cell for free travel?' }],
      modifiers: [{ target: 'cost.travel', set: 0, ask: 'use' }], consumeOn: 'cost.travel'
    },
    {
      id: 'insider-info', name: 'Insider information', scope: 'campaign',
      text: 'A Patron search succeeds automatically. Single-use.',
      modifiers: [{ target: 'roll.patron', floor: 5 }], consumeOn: 'roll.patron'
    },

    /* ------------------------------------------------------------------ */
    /* Rival                                                               */
    {
      id: 'follows', name: 'Follows you', scope: 'rival',
      text: 'Follows you from planet to planet until resolved. +1 enemy in battles against them.',
      modifiers: [{ target: 'enemies', add: 1 }], endsOn: 'rivalResolved'
    },
    {
      id: 'first-meeting', name: 'Already knocked one out', scope: 'rival',
      text: 'The first time you meet them in battle, they have -1 enemy.',
      modifiers: [{ target: 'enemies', add: -1 }], consumeOn: 'battleResult'
    }
  ];

  LP.data = LP.data || {};
  LP.data.basePack = {
    format: 'last-parsec-events', version: 1,
    pack: { id: 'base', name: 'Base events', author: 'Last Parsec', version: '1.0', description: 'The events and conditions from the rulebook, adjusted to play inside the app.' },
    events: LP.data.baseEvents.events,
    conditions: conditions,
    fragments: LP.data.baseEvents.fragments
  };
})(window.LP);
